<?php
require __DIR__ . '/_boot.php';
$pageTitle = 'Flowers & inventory'; $pageDescription = 'Keep every arrangement looking its best and its stock up to date.'; $headingAction = ['path' => '/admin/product-edit.php', 'label' => '+ Add arrangement'];
$products = db()->query('SELECT p.*,c.name AS category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.is_active DESC,p.id DESC')->fetchAll();
require dirname(__DIR__, 2) . '/templates/admin_header.php';
?>
<section class="panel"><?php if (!$products): ?><div class="empty-state"><h2>Room for something beautiful.</h2><p>Add an arrangement to start your catalog.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Arrangement</th><th>Category</th><th>Price</th><th>Stock</th><th>Visibility</th><th>Actions</th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><div class="product-cell"><img src="<?= e(url('/' . $product['image_path'])) ?>" alt=""><a href="<?= e(url('/admin/product-edit.php?id=' . $product['id'])) ?>"><?= e($product['name']) ?></a></div></td><td><?= e($product['category_name']) ?></td><td><?= e(format_money($product['price'])) ?></td><td><span class="<?= (int)$product['stock_quantity'] === 0 ? 'low-stock' : '' ?>"><?= (int)$product['stock_quantity'] ?></span></td><td><span class="status <?= $product['is_active'] ? 'status-completed' : '' ?>"><?= $product['is_active'] ? 'Active' : 'Archived' ?></span></td><td><div class="row-actions"><a href="<?= e(url('/admin/product-edit.php?id=' . $product['id'])) ?>">Edit</a><?php if ($product['is_active']): ?><form method="post" action="<?= e(url('/admin/actions/product-archive.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$product['id'] ?>"><button class="text-button danger" type="submit">Archive</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><p class="help-text">Archiving removes an arrangement from the storefront and keeps existing order receipts intact.</p>
<?php require dirname(__DIR__, 2) . '/templates/admin_footer.php'; ?>
